const f = $json;
const lingua = (f.lingua_sito || 'italiano').trim();

const system = 'Sei un esperto di siti web ad alta conversione per attivita\' locali di servizi. Scrivi brief dettagliati e pronti all\'uso per AI website builder (Framer, Lovable, Webflow AI, Wix AI). Il brief deve essere cosi\' completo che il builder produca un sito professionale al primo colpo.';

const prompt = `Sto costruendo un sito web ad alta conversione per ${f.nome_attivita}, ${f.categoria} a ${f.citta}. In base ai loro servizi e alle recensioni positive dei clienti, scrivi un prompt professionale e dettagliato per un AI website builder. Il sito deve essere in ${lingua}.\n\nIl brief deve includere sezioni per:\n- Hero header con il servizio principale e gli anni di esperienza (${f.anni_esperienza || 'non specificati'})\n- Sezione prenotazione/richiesta preventivo con TUTTI i loro servizi elencati\n- Sezione testimonianze usando le loro recensioni Google REALI (riformattate ma fedeli)\n- Sezione Chi Siamo che enfatizza esperienza e segnali di fiducia (zona servita: ${f.citta})\n- Pulsanti call-to-action chiari e ripetuti (telefono: ${f.telefono || 'da inserire'})\n- Indicazioni su palette colori e tipografia adatte al settore ${f.categoria} (NIENTE estetica generica da AI: no gradienti viola, no font di sistema)\n- Note SEO locale: title tag, meta description e H1 con \"${f.categoria} ${f.citta}\"\n\nI loro servizi:\n${f.servizi}\n\nLe loro recensioni migliori:\n${f.recensioni_migliori}\n\nProduci SOLO il brief finale pronto da incollare nel builder.`;

return {
  json: {
    dati: f,
    anthropic_request: {
      model: 'claude-opus-4-8',
      max_tokens: 4096,
      system,
      messages: [{ role: 'user', content: prompt }],
    },
  },
};

const text = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const dati = $('Prepara brief').item.json.dati;
return {
  json: {
    subject: 'Brief sito web: ' + dati.nome_attivita + ' (' + dati.citta + ')',
    body: text,
  },
};
